"""Tests for the IQR + isolated-zero anomaly detection pipeline."""
import json
import subprocess
import sys

import pytest

sys.path.insert(0, ".")

import detect  # noqa: E402

SPIKE_DAYS = {50, 200, 350}
GLITCH_DAYS = {120, 280}
QUIET_STRETCH_DAYS = {390, 391, 392}
EXPECTED_SPIKE_VALUES = {50: 66, 200: 78, 350: 75}


@pytest.fixture(scope="module", autouse=True)
def pipeline():
    """Run the full generate -> detect pipeline once for the module."""
    r1 = subprocess.run([sys.executable, "gen.py"], capture_output=True, text=True)
    assert r1.returncode == 0, r1.stderr
    r2 = subprocess.run([sys.executable, "detect.py"], capture_output=True, text=True)
    assert r2.returncode == 0, r2.stderr
    with open("anomalies.json") as f:
        return json.load(f)


@pytest.fixture(scope="module")
def anomalies(pipeline):
    return pipeline


# ---------------------------------------------------------------- schema

def test_schema_top_level_is_list(anomalies):
    assert isinstance(anomalies, list)
    assert len(anomalies) > 0


@pytest.mark.parametrize("entry_idx", range(5))
def test_schema_fields(anomalies, entry_idx):
    entry = anomalies[entry_idx]
    # exact field set: day, value, kind — no extras, no missing
    assert set(entry.keys()) == {"day", "value", "kind"}
    assert isinstance(entry["day"], int) and not isinstance(entry["day"], bool)
    assert isinstance(entry["value"], int) and not isinstance(entry["value"], bool)
    assert entry["kind"] in {"spike", "glitch"}
    assert 0 <= entry["day"] < 400
    assert entry["kind"] == "spike" or entry["value"] == 0
    if entry["kind"] == "spike":
        assert 60 <= entry["value"] <= 80


def test_entries_sorted_by_day(anomalies):
    days = [a["day"] for a in anomalies]
    assert days == sorted(days)


# ------------------------------------------------------- planted anomalies

def test_exactly_five_planted_days_flagged(anomalies):
    flagged = {(a["day"]) for a in anomalies}
    assert flagged == SPIKE_DAYS | GLITCH_DAYS


def test_no_other_day_flagged(anomalies):
    flagged = [a["day"] for a in anomalies]
    assert len(flagged) == len(set(flagged)), "duplicate day entries"
    for a in anomalies:
        assert a["day"] not in set(range(400)) - (SPIKE_DAYS | GLITCH_DAYS)


def test_spike_days_and_kinds(anomalies):
    by_day = {a["day"]: a for a in anomalies}
    for d in SPIKE_DAYS:
        assert by_day[d]["kind"] == "spike"
        assert by_day[d]["value"] == EXPECTED_SPIKE_VALUES[d]


def test_glitch_days_and_kinds(anomalies):
    by_day = {a["day"]: a for a in anomalies}
    for d in GLITCH_DAYS:
        assert by_day[d]["kind"] == "glitch"
        assert by_day[d]["value"] == 0


def test_kinds_partition(anomalies):
    kinds = [a["kind"] for a in anomalies]
    assert kinds.count("spike") == 3
    assert kinds.count("glitch") == 2


# ------------------------------------------- legitimate quiet stretch

def test_quiet_stretch_not_flagged_as_glitches(anomalies):
    flagged = {a["day"]: a for a in anomalies}
    for d in QUIET_STRETCH_DAYS:
        assert d not in flagged, (
            f"day {d} wrongly flagged as {flagged.get(d)}"
        )


def test_quiet_stretch_exists_in_data():
    values = detect.load_series()
    assert all(values[d] == 0 for d in QUIET_STRETCH_DAYS), \
        "quiet stretch of three consecutive zeros must be present in the data"

